\"\"\"
openai_client — Send private text prompts to OpenAI's Responses API.

Requires no third‑party packages.  Reads the API key from the
"'``OPENAI_API_KEY`` environment variable.

Usage::

    import openai_client

    client = openai_client.Client()
    reply = client.ask("Why is the sky blue?")
    print(reply)

    # Or stream tokens as they arrive:
    for token_text in client.ask_stream("Tell me a joke"):
        print(token_text, end="", flush=True)

    # Attach previous turn IDs for conversation continuity:
    reply2, previous_id = client.ask("What about at sunset?", previous_response_id=reply1_id)
"""

from __future__ import annotations

import json
import os
import ssl
import sys
from typing import Iterator
from urllib import request
from urllib.error import HTTPError, URLError

# ---------------------------------------------------------------------------
# Public helpers
# ---------------------------------------------------------------------------

__all__ = ["Client", "APIError"]

DEFAULT_MODEL = "gpt-4o-mini"
DEFAULT_BASE_URL = "https://api.openai.com/v1/responses"


class APIError(Exception):
    """Raised when the API returns a non‑2xx status or a network issue occurs."""

    def __init__(self, message: str, *, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


# ---------------------------------------------------------------------------
# Client
# ---------------------------------------------------------------------------


class Client:
    """Thin wrapper around the OpenAI Responses API (stdlib only)."""

    def __init__(
        self,
        *,
        api_key: str | None = None,
        model: str = DEFAULT_MODEL,
        base_url: str = DEFAULT_BASE_URL,
    ) -> None:
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY", "")
        if not self.api_key:
            raise APIError(
                "No API key provided — set OPENAI_API_KEY or pass api_key="
            )
        self.model = model
        self.base_url = base_url

    # -- Public API -----------------------------------------------------------

    def ask(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        previous_response_id: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
    ) -> tuple[str, str | None]:
        """Send a single text prompt and return ``(text, previous_response_id)``.

        The returned ``previous_response_id`` can be fed back as the
        ``previous_response_id`` of a subsequent call to maintain
        conversational state (analogous to a thread).
        """
        payload: dict = {
            "model": model or self.model,
            "input": prompt,
        }

        # -- Optional parameters --
        if instructions is not None:
            payload["instructions"] = instructions
        if previous_response_id is not None:
            payload["previous_response_id"] = previous_response_id
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens

        data = self._request("POST", payload)
        text = _extract_text(data)

        # The API returns an ``id`` field we can use to continue the conversation.
        resp_id: str | None = data.get("id")
        return text, resp_id

    def ask_stream(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        previous_response_id: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
    ) -> Iterator[str]:
        """Like :meth:`ask` but yields text tokens as they arrive (SSE streaming)."""
        payload: dict = {
            "model": model or self.model,
            "input": prompt,
            "stream": True,
        }

        if instructions is not None:
            payload["instructions"] = instructions
        if previous_response_id is not None:
            payload["previous_response_id"] = previous_response_id
        if temperature is not None:
            payload["temperature"] = temperature
        if max_output_tokens is not None:
            payload["max_output_tokens"] = max_output_tokens

        # Build the URL for the stream endpoint.  The Responses API may append
        # ``/stream`` — we handle both conventions.
        url = self.base_url.rstrip("/")

        req = request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
                "Accept": "text/event-stream",
            },
            method="POST",
        )

        try:
            ctx = ssl.create_default_context()
            with request.urlopen(req, context=ctx) as resp:  # type: ignore[attr-defined]
                for raw_line in resp:
                    line = raw_line.decode("utf-8").strip()
                    if not line or line.startswith(":"):
                        continue
                    if line.startswith("data: "):
                        data_str = line[len("data: "):]
                        if data_str == "[DONE]":
                            break
                        try:
                            event = json.loads(data_str)
                        except json.JSONDecodeError:
                            continue
                        token = [REDACTED_SECRET]
                        if token:
                            yield token
        except HTTPError as exc:
            raise _build_http_error(exc) from exc
        except URLError as exc:
            raise APIError(f"Network error: {exc.reason}") from exc

    # -- Internals ------------------------------------------------------------

    def _request(self, method: str, payload: dict) -> dict:
        """Send a JSON request and return the decoded JSON body."""
        url = self.base_url.rstrip("/")
        req = request.Request(
            url,
            data=json.dumps(payload).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
            },
            method=method,
        )

        try:
            ctx = ssl.create_default_context()
            with request.urlopen(req, context=ctx) as resp:  # type: ignore[attr-defined]
                body = resp.read().decode("utf-8")
                return json.loads(body)
        except HTTPError as exc:
            raise _build_http_error(exc) from exc
        except URLError as exc:
            raise APIError(f"Network error: {exc.reason}") from exc


# ---------------------------------------------------------------------------
# Response extraction helpers
# ---------------------------------------------------------------------------


def _extract_text(data: dict) -> str:
    """Walk the Responses‑API JSON structure and return concatenated text."""
    output: list[dict] = data.get("output", [])
    parts: list[str] = []

    for item in output:
        if item.get("type") != "message":
            continue
        for content_block in item.get("content", []):
            if content_block.get("type") == "output_text":
                parts.append(content_block.get("text", ""))

    return "'"\\n\".join(parts)


def _extract_stream_token(event: dict) -> str | None:
    \"\"\"Extract a content delta from a single streaming SSE event.

    The Responses API streaming shape is still evolving, so we try several
    common patterns.
    \"\"\"
    event_type = event.get(\"type\", \"\")

    # Pattern 1: "'``response.output_text.delta``
    if event_type == "response.output_text.delta":
        return event.get("delta", "")

    # Pattern 2: delta embedded in ``content_block``
    if event_type == "response.content_part.added":
        block = event.get("part") or event.get("content_block") or {}
        if isinstance(block, dict):
            return block.get("text", "")

    # Pattern 3: top‑level ``delta`` key
    delta = event.get("delta")
    if isinstance(delta, str):
        return delta

    # Pattern 4: ``text`` key in a ``delta`` sub‑object
    if isinstance(delta, dict):
        return delta.get("text")

    return None


def _build_http_error(exc: HTTPError) -> APIError:
    try:
        body = exc.read().decode("utf-8")
        detail = json.loads(body)
        msg = detail.get("error", {}).get("message", exc.reason)
    except Exception:
        msg = exc.reason
    return APIError(msg, status=exc.code)


# ---------------------------------------------------------------------------
# Quick CLI entry point (``python -m openai_client`` → interactive REPL)
# ---------------------------------------------------------------------------

def main() -> None:
    """Minimal interactive loop for quick testing."""
    client = Client()
    prev_id: str | None = None

    print(f"openai_client — model: {client.model}")
    print("Type '"'quit' or Ctrl‑C to exit.\\n\")

    while True:
        try:
            prompt = input(\"> \").strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break

        if prompt.lower() in {\"quit\", \"exit\", \"q\"}:
            break
        if not prompt:
            continue

        try:
            text, prev_id = client.ask(prompt, previous_response_id=prev_id)
            print(text)
            print()
        except APIError as exc:
            print(f\"[API error ({exc.status})] {exc}\")
            print()


if __name__ == \"__main__\":
    main()
